        public static float CentreOf(string key, float height)
        {
            if (key == null || !Centre.TryGetValue(key, out var c) || !All.TryGetValue(key, out var p) || height < 0f) return 0f;
            int row = (int)(height * p.ppt); return row >= c.Length ? 0f : c[row];
        }

        /// <summary>The silhouette's half-width at `height` tiles above the feet, or -1 above the crown or for a body without a profile.</summary>
        public static float Half(string key, float height)
        {
            if (key == null || !All.TryGetValue(key, out var p) || height < 0f) return -1f;
            int row = (int)(height * p.ppt); if (row >= p.half.Length) return -1f;
            return p.half[row];
        }

        /// <summary>How deep a body is front to back as a cap on its half-width (tiles): a hound is long on screen but thin, so a round that comes along its length sees only this much of it; 9 = no cap.</summary>
