        public static bool HasRuns(string key) => key != null && Runs.ContainsKey(key);
        /// <summary>The runs of the picture's row `height` tiles above the feet, or null above the crown (or for a body without an outline).</summary>
        public static float[] RunsAt(string key, float height)
        {
            if (key == null || height < 0f || !Runs.TryGetValue(key, out var r) || !All.TryGetValue(key, out var p)) return null;
            int row = (int)(height * p.ppt); return row >= r.Length ? null : r[row];
        }

