                new[] { 0.447f, 0.974f },
                new[] { 0.237f, 0.868f },
                new[] { 0.211f, 0.868f },
                new[] { 0.211f, 0.868f },
                new[] { 0.211f, 0.816f },
                new[] { 0.237f, 0.737f },
                new[] { 0.368f, 0.447f, 0.632f, 0.711f },
            },
        };

        public static float[] AttackRunsAt(string key, string kind, float height)
        {
            if (key == null || kind == null || height < 0f || !AttackRuns.TryGetValue(key + "|" + kind, out var r) || !All.TryGetValue(key, out var p)) return null;
            int row = (int)(height * p.ppt); return row >= r.Length ? null : r[row];
        }

        /// <summary>The silhouette's height in tiles (feet to crown), 0 for a body without one.</summary>
        public static float Height(string key) => key != null && All.TryGetValue(key, out var p) ? (Runs.TryGetValue(key, out var rr) ? rr.Length : p.half.Length) / (float)p.ppt : 0f;
    }
}
